text:
header {
  display: grid;
  grid-template-columns: 1fr max-content;
  grid-template-rows: 1fr;
  gap: 9px 6px;
  align-items: center;
  position: sticky;
  inset-block-start: 0;
  padding: 9px 12px;
  background: var(--color-surface-lower);
  color: var(--color-text-base);
  border-block-end: 1px solid var(--color-surface-border);
